package com.bank.slo;

// An SLO = a target for an SLI over the window.
public class SloTarget {
    private final String sliName;
    private final double targetPercent;   // e.g. 99.9

    public SloTarget(String sliName, double targetPercent) {
        this.sliName = sliName;
        this.targetPercent = targetPercent;
    }

    public String getSliName() { return sliName; }
    public double getTargetPercent() { return targetPercent; }

    // Error budget = allowed failure = 100 - target (in percentage points).
    public double errorBudgetPercent() { return 100.0 - targetPercent; }
}
