package com.bank.slo;

import java.util.List;
import java.util.logging.Logger;

public class SloEvaluator {
    private static final Logger log = Logger.getLogger(SloEvaluator.class.getName());
    private final long latencyThresholdMs;

    public SloEvaluator(long latencyThresholdMs) {
        this.latencyThresholdMs = latencyThresholdMs;
    }

    // Availability SLI: successful / total.
    public Sli availabilitySli(List<RequestOutcome> window) {
        long total = window.size();
        long good = window.stream().filter(RequestOutcome::isSuccess).count();
        double pct = total == 0 ? 100 : (good * 100.0 / total);
        return new Sli("availability", pct);
    }

    // Latency SLI: requests under threshold / total.
    public Sli latencySli(List<RequestOutcome> window) {
        long total = window.size();
        long fast = window.stream().filter(o -> o.getLatencyMs() <= latencyThresholdMs).count();
        double pct = total == 0 ? 100 : (fast * 100.0 / total);
        return new Sli("latency(<=" + latencyThresholdMs + "ms)", pct);
    }

    // Compare SLI to SLO, report pass/fail + how much error budget is left.
    public boolean evaluate(Sli sli, SloTarget slo) {
        boolean met = sli.getPercent() >= slo.getTargetPercent();
        double budget = slo.errorBudgetPercent();           // allowed failure
        double actualFailure = 100.0 - sli.getPercent();    // observed failure
        double consumedPct = budget == 0 ? 0 : (actualFailure / budget) * 100.0;
        if (met) {
            log.info(() -> String.format("%s SLI=%.3f%% >= SLO=%.3f%% → MET. "
                + "Error budget consumed: %.1f%% (room to ship).",
                sli.getName(), sli.getPercent(), slo.getTargetPercent(), consumedPct));
        } else {
            log.severe(() -> String.format("%s SLI=%.3f%% < SLO=%.3f%% → BREACHED. "
                + "Error budget consumed: %.1f%% (freeze features, fix reliability).",
                sli.getName(), sli.getPercent(), slo.getTargetPercent(), consumedPct));
        }
        return met;
    }
}
