package com.bank.slo;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.*;

public class SloDemo {
    private static final Logger log = Logger.getLogger(SloDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Simulated 30-day window: 10,000 transfer requests.
        List<RequestOutcome> window = new ArrayList<>();
        for (int i = 0; i < 10_000; i++) {
            boolean success = i % 2000 != 0;           // ~5 failures per 10k → 99.95%
            long latency = (i % 50 == 0) ? 450 : 120;  // ~2% slow (>300ms)
            window.add(new RequestOutcome(success, latency));
        }

        SloEvaluator evaluator = new SloEvaluator(300);
        log.info("National Bank of India transfer-api — 30-day SLO report");

        Sli avail = evaluator.availabilitySli(window);
        evaluator.evaluate(avail, new SloTarget("availability", 99.9));   // target 99.9%

        Sli latency = evaluator.latencySli(window);
        evaluator.evaluate(latency, new SloTarget(latency.getName(), 99.0)); // target 99%
    }
}
